// Local file storage for photos, GIFs, videos and site images.
//
// Keys are RELATIVE identifiers generated by the server only, e.g.
//   photos/2027-01/<uuid>.jpg   photos/2027-01/<uuid>_thumb.jpg
//   photos/2027-01/<uuid>.gif   photos/2027-01/<uuid>.mp4   site/<uuid>.jpg
// They are resolved against UPLOAD_DIRECTORY and re-checked so no key can
// escape that directory (path traversal). User-supplied filenames are never
// used. To move to object storage later, replace the functions below.
import fs from 'node:fs/promises'
import path from 'node:path'
import { config } from '../config.js'

const KEY_RE = /^(photos\/\d{4}-\d{2}\/[0-9a-f-]{36}(_thumb)?\.(jpg|gif|mp4|webm)|site\/[0-9a-f-]{36}\.jpg)$/

export const CONTENT_TYPES = { jpg: 'image/jpeg', gif: 'image/gif', mp4: 'video/mp4', webm: 'video/webm' }

/** Incomplete uploads land here first and are never served. */
export const tmpDir = () => path.join(config.uploads.dir, '.tmp')

export function resolveKey(key) {
  if (typeof key !== 'string' || !KEY_RE.test(key)) throw new Error(`Invalid storage key: ${key}`)
  const root = config.uploads.dir
  const full = path.resolve(root, key)
  if (!full.startsWith(root + path.sep)) throw new Error('Storage key escapes upload directory')
  return full
}

export const contentTypeForKey = (key) => CONTENT_TYPES[key.split('.').pop()] ?? 'application/octet-stream'

export async function saveFile(key, buffer) {
  const target = resolveKey(key)
  await fs.mkdir(path.dirname(target), { recursive: true })
  await fs.writeFile(target, buffer, { flag: 'wx', mode: 0o640 })
}

/** Moves a fully received temp file into its final key (no copy for large videos). */
export async function moveIntoPlace(tempPath, key) {
  const target = resolveKey(key)
  const temp = path.resolve(tempPath)
  if (!temp.startsWith(path.resolve(tmpDir()) + path.sep)) throw new Error('Temp file outside upload temp directory')
  await fs.mkdir(path.dirname(target), { recursive: true })
  try {
    await fs.access(target)
    throw new Error(`Refusing to overwrite ${key}`)
  } catch (error) {
    if (error.code !== 'ENOENT') throw error
  }
  try {
    await fs.rename(temp, target)
  } catch (error) {
    if (error.code !== 'EXDEV') throw error
    await fs.copyFile(temp, target, fs.constants.COPYFILE_EXCL)
    await fs.rm(temp, { force: true })
  }
}

export async function removeFiles(keys) {
  await Promise.all(
    [...new Set(keys.filter(Boolean))].map((k) =>
      fs.rm(resolveKey(k), { force: true }).catch((e) => console.error('[wedding-api] could not delete', k, e.code)),
    ),
  )
}

/** Deletes request temp files (called after every upload, success or failure). */
export async function removeTemp(paths) {
  await Promise.all(paths.filter(Boolean).map((p) => fs.rm(p, { force: true }).catch(() => {})))
}

/** Removes temp files left behind by aborted uploads (older than one hour). */
export async function sweepTemp() {
  const dir = tmpDir()
  const entries = await fs.readdir(dir).catch(() => [])
  const cutoff = Date.now() - 3600 * 1000
  for (const name of entries) {
    const file = path.join(dir, name)
    const stat = await fs.stat(file).catch(() => null)
    if (stat && stat.mtimeMs < cutoff) await fs.rm(file, { force: true }).catch(() => {})
  }
}

export async function ensureUploadDir() {
  await fs.mkdir(tmpDir(), { recursive: true })
}
